use crate::*;

const EXAMPLES: &[BuiltinExample] = &[
    BuiltinExample { id: "warning-1", title: "Displaying a simple warning", program: "warning(\"Computation took longer than expected.\")\nlast = warning('query', 'last');", display_output: None, compatibility: BuiltinExampleCompatibility::Matlab, harness: BuiltinExampleHarness::Portable, fixture: BuiltinExampleFixture::None, requirements: BuiltinExampleRequirements::NONE, verification: BuiltinExampleVerification::Assertions { source: "assert(strcmp(last.message, 'Computation took longer than expected.'));" } },
    BuiltinExample { id: "warning-2", title: "Emitting a warning with a custom identifier", program: "warning(\"runmat:io:deprecatedOption\", ...\n        \"Option '%s' is deprecated and will be removed in %s.\", ...\n        \"VerboseMode\", \"1.2\")\nlast = warning('query', 'last');", display_output: None, compatibility: BuiltinExampleCompatibility::Matlab, harness: BuiltinExampleHarness::Portable, fixture: BuiltinExampleFixture::None, requirements: BuiltinExampleRequirements::NONE, verification: BuiltinExampleVerification::Assertions { source: "assert(strcmp(last.identifier, 'runmat:io:deprecatedOption'));" } },
    BuiltinExample { id: "warning-3", title: "Turning a specific warning off and back on", program: "warning(\"off\", \"runmat:io:deprecatedOption\");\n% ... code that triggers the warning ...\nwarning(\"on\", \"runmat:io:deprecatedOption\")\nstate = warning('query', 'runmat:io:deprecatedOption');", display_output: None, compatibility: BuiltinExampleCompatibility::Matlab, harness: BuiltinExampleHarness::Portable, fixture: BuiltinExampleFixture::None, requirements: BuiltinExampleRequirements::NONE, verification: BuiltinExampleVerification::Assertions { source: "assert(strcmp(state.state, 'on'));" } },
    BuiltinExample { id: "warning-4", title: "Promoting a warning to an error", program: "warning(\"error\", \"runmat:solver:illConditioned\");\n% The next call raises an error instead of printing a warning.\nwarning(\"runmat:solver:illConditioned\", ...\n        \"Condition number exceeds threshold %.2e.\", 1e12)", display_output: None, compatibility: BuiltinExampleCompatibility::Matlab, harness: BuiltinExampleHarness::Portable, fixture: BuiltinExampleFixture::None, requirements: BuiltinExampleRequirements::NONE, verification: BuiltinExampleVerification::ExpectedError { identifier: "runmat:solver:illConditioned" } },
    BuiltinExample { id: "warning-5", title: "Querying and restoring warning state", program: "state = warning(\"query\", \"all\");   % capture the current table\nwarning(\"off\", \"all\");              % silence all warnings temporarily\nwarning(\"Some temporary warning.\");\nwarning(state);                    % restore original configuration\nrestored = warning('query', 'all');", display_output: None, compatibility: BuiltinExampleCompatibility::Matlab, harness: BuiltinExampleHarness::Portable, fixture: BuiltinExampleFixture::None, requirements: BuiltinExampleRequirements::NONE, verification: BuiltinExampleVerification::Assertions { source: "assert(iscell(restored)); assert(isequal(restored, state));" } },
    BuiltinExample { id: "warning-6", title: "Enabling backtraces for debugging", program: "warning(\"on\", \"backtrace\");   % warning(\"backtrace\",\"on\") is equivalent\nwarning(\"runmat:demo:slowPath\", \"Inspect the call stack above for context.\");\nduring = warning('query', 'backtrace');\nwarning(\"off\", \"backtrace\")", display_output: None, compatibility: BuiltinExampleCompatibility::Matlab, harness: BuiltinExampleHarness::Portable, fixture: BuiltinExampleFixture::None, requirements: BuiltinExampleRequirements::NONE, verification: BuiltinExampleVerification::Assertions { source: "assert(strcmp(during.state, 'on'));" } },
    BuiltinExample { id: "warning-7", title: "Displaying verbose suppression guidance", program: "warning(\"on\", \"verbose\");\nwarning(\"runmat:demo:slowPath\", \"Inspect the call stack above for context.\");\nduring = warning('query', 'verbose');\nwarning(\"default\", \"verbose\");   % restore the default verbosity", display_output: None, compatibility: BuiltinExampleCompatibility::Matlab, harness: BuiltinExampleHarness::Portable, fixture: BuiltinExampleFixture::None, requirements: BuiltinExampleRequirements::NONE, verification: BuiltinExampleVerification::Assertions { source: "assert(strcmp(during.state, 'on'));" } },
];

pub(super) const DOCUMENTATION: BuiltinDocumentation = BuiltinDocumentation {
    authority: BuiltinDocumentationAuthority::Catalog, title: Some("warning"), slug: Some("warning"), summary: "Emit formatted warnings and control warning state by identifier.", description: "`warning` emits non-fatal diagnostic messages and manages warning enable/disable/error states globally or per identifier, following MATLAB-compatible control forms.",
    keywords: &["warning", "diagnostics", "state", "query", "backtrace"], related: &["error", "sprintf", "fprintf", "assert"],
    sections: &[BuiltinDocumentationSection { heading: "Behavior and placement",
        paragraphs: &["`warning(message)` prints the message using the default identifier `RunMat:warning`.",
        "`warning(id, fmt, args...)` associates the warning with the identifier `id`, formats the message using MATLAB's `sprintf` rules, and honours per-identifier state.",
        "Numeric scalar formatting values include every integer class and are formatted from authoritative storage, so wide signed and unsigned values remain exact.",
        "Nonscalar integer formatting arrays are a gated RunMat extension and are consumed in column-major order.",
        "`warning(MException_obj)` reissues an existing exception as a warning.",
        "`warning(struct)` restores warning state previously captured with `warning('query', ...)`.",
        "`warning(state, id)` changes the mode for `id` (`'on'`, `'off'`, `'once'`, `'error'`, and the aliases `'all'` or `'last'`). The call returns a struct describing the prior state so you can restore it later.",
        "`warning(state, mode)` controls diagnostic verbosity modes such as `'backtrace'` and `'verbose'`, returning a struct snapshot of the previous setting.",
        "`warning('default', id)` resets `id` (or `'all'`, `'backtrace'`, `'verbose'`, `'last'`) to the factory default, returning the state that was active before the reset. `warning('reset')` restores every warning, mode, and once-tracking flag in one call.",
        "`warning('query', id)` returns a struct describing the current mode for `id`. Passing `'all'` returns a cell vector of structs covering every configured identifier plus the global default and diagnostic modes.",
        "`warning('status')` prints the global warning table as a formatted summary.",
        "All state-changing forms return struct snapshots; pass them back to `warning` later to reinstate the captured state.",
        "`warning` is a control-flow builtin that runs on the host. Resident formatting arguments are rejected without launching a provider operation.",
        "No GPU kernel or automatic gather is used by `warning`."] }],
    examples: EXAMPLES, example_exemption: None,
        faqs: &[BuiltinDocumentationFaq { question: "Does RunMat keep track of the last warning?",
        answer: "Yes. The last identifier and message are stored internally and will be exposed through the MATLAB-compatible `lastwarn` builtin." },
        BuiltinDocumentationFaq { question: "What does `'once'` do?",
        answer: "The first occurrence of the warning is shown, and subsequent uses of the same identifier are suppressed until you change the state." },
        BuiltinDocumentationFaq { question: "How do I restore defaults after experimentation?",
        answer: "Call `warning('reset')` to revert the global default, per-identifier table, diagnostic modes, and once-tracking." },
        BuiltinDocumentationFaq { question: "Do state-changing calls return anything useful?",
        answer: "Yes. Forms such as `warning('off','id')`, `warning('on','backtrace')`, and `warning('default')` return struct snapshots describing the state before the change. Store the struct and pass it back to `warning` later to restore the captured configuration." },
        BuiltinDocumentationFaq { question: "What does the `'verbose'` mode do?",
        answer: "When enabled (`warning('on','verbose')`), RunMat prints an additional hint describing how to suppress the warning. Disable it with `warning('default','verbose')`." },
        BuiltinDocumentationFaq { question: "What happens when a warning is promoted to `'error'`?",
        answer: "The warning text is reused to raise an error with the same identifier, just like MATLAB." },
        BuiltinDocumentationFaq { question: "Does `warning` run on the GPU?",
        answer: "No. Control-flow builtins execute on the host, and resident formatting values are rejected rather than gathered implicitly." },
        BuiltinDocumentationFaq { question: "Can I provide multiple state structs to `warning(state)`?",
        answer: "Yes. Pass either a struct or a cell array of structs (as returned by `warning('query','all')`); RunMat applies them sequentially." },
        BuiltinDocumentationFaq { question: "Does `warning('on','backtrace')` match MATLAB output exactly?",
        answer: "RunMat prints a Rust backtrace for now. Future releases will map this to MATLAB-style stack frames, but the enable/disable semantics match MATLAB." },
        BuiltinDocumentationFaq { question: "Is whitespace in identifiers allowed?",
        answer: "Identifiers follow MATLAB rules: they must contain at least one colon and no whitespace. RunMat normalises bare names by prefixing `RunMat:`." },
        BuiltinDocumentationFaq { question: "What if I call `warning` with unsupported arguments?",
        answer: "RunMat issues a MATLAB-compatible usage error so you can correct the call." },
        BuiltinDocumentationFaq { question: "Are repeated calls thread-safe?",
        answer: "Warning policy is scoped to the active runtime context, with a thread-local fallback outside one; calls do not share a process-global mutex-protected warning table." }],
    links: &[BuiltinDocumentationLink { label: "error", target: BuiltinDocumentationLinkTarget::Builtin("error") }, BuiltinDocumentationLink { label: "sprintf", target: BuiltinDocumentationLinkTarget::Builtin("sprintf") }, BuiltinDocumentationLink { label: "fprintf", target: BuiltinDocumentationLinkTarget::Builtin("fprintf") }, BuiltinDocumentationLink { label: "assert", target: BuiltinDocumentationLinkTarget::Builtin("assert") }],
    media: &[], evidence: BuiltinDocumentationEvidence { implementation: &[BuiltinDocumentationLink { label: "Runtime warning state", target: BuiltinDocumentationLinkTarget::Source("https://github.com/runmat-org/runmat/blob/main/crates/runmat-runtime/src/builtins/diagnostics/warning.rs") }, BuiltinDocumentationLink { label: "Warning emission", target: BuiltinDocumentationLinkTarget::Source("https://github.com/runmat-org/runmat/blob/main/crates/runmat-runtime/src/warnings/emission.rs") }], verification: &[BuiltinEvidenceReference { kind: BuiltinEvidenceKind::UnitTest, label: "warning runtime semantics", location: "crates/runmat-runtime/src/builtins/diagnostics/warning.rs tests" }], notes: &[] }, introduced: None, status: Some(BuiltinDocumentationStatus::Partial),
};
